    ".oxfmtrc.json":
      '{\n  "$schema": "./node_modules/oxfmt/configuration_schema.json",\n  "printWidth": 80,\n  "proseWrap": "always"\n}\n',
    "AGENTS.md":
      "# AGENTS.md\n\n## Repository Contract\n\n- This repository is the standalone source of truth for the Noter starter app.\n- It should remain a self-sustained full-stack repo, not a partial export from\n  the Noter monorepo.\n- Noter currently consumes this repo as a pinned latest snapshot, not as a\n  replayed commit history.\n- Keep the repo shaped as a monorepo with a single app in `apps/web`.\n- The stack baseline should stay aligned with the shared Vite Plus app setup\n  that Noter expects seeded repos to use.\n- Keep the repo clean enough that making it public later remains realistic.\n\n## Maintenance Rules\n\n1. Keep the root workspace scripts working for the repo as exported.\n2. When changing scaffold-critical config like Vite Plus setup, `vite.config`,\n   `tsconfig`, lint config, or format config, keep the changes deliberate and\n   reviewable because Noter-managed starter sync depends on them.\n3. Keep runtime-owned assets in this repo unless there is a concrete reason to\n   move them back behind monorepo sync.\n4. Prefer readable changes, but do not treat history shape as part of the\n   current seeding contract.\n",
    "apps/web/.gitignore":
      "# Keep broadly aligned with the source starter template so extraction stays\n# predictable.\n\n# Logs\nlogs\n*.log\nnpm-debug.log*\nyarn-debug.log*\nyarn-error.log*\npnpm-debug.log*\nlerna-debug.log*\n\n# Dependencies\nnode_modules\n.pnp\n.pnp.js\n\n# Production builds\ndist\ndist-ssr\nbuild\n.next\n\n# Coverage\ncoverage\n.nyc_output\n\n# Tooling caches\n*.tsbuildinfo\n.turbo\n.vite\n\n# Environment variables\n*.local\n.env\n.env.local\n.env.production.local\n.env.development.local\n\n# Convex\nconvex/_generated\nconvex/.tmp\n.convex\n\n# Editor directories and files\n.vscode/*\n!.vscode/extensions.json\n.idea\n.DS_Store\n*.suo\n*.ntvs*\n*.njsproj\n*.sln\n*.sw?\n\n# Package manager lockfiles (keeping pnpm-lock.yaml)\npackage-lock.json\nyarn.lock\n",
    "apps/web/.oxfmtrc.json":
      '{\n  "$schema": "./node_modules/oxfmt/configuration_schema.json",\n  "printWidth": 80,\n  "proseWrap": "always"\n}\n',
    "apps/web/components.json":
      '{\n  "$schema": "https://ui.shadcn.com/schema.json",\n  "style": "new-york",\n  "rsc": false,\n  "tsx": true,\n  "tailwind": {\n    "config": "tailwind.config.ts",\n    "css": "src/index.css",\n    "baseColor": "slate",\n    "cssVariables": true,\n    "prefix": ""\n  },\n  "aliases": {\n    "components": "@/components",\n    "utils": "@/lib/utils"\n  }\n}\n',
    "apps/web/convex/messages.ts":
      'import { query } from "./_generated/server";\n\nexport const getWelcomeMessage = query({\n  args: {},\n  handler: async () => {\n    return {\n      title: "Convex is wired",\n      detail: "The next step is layering in the starter UI and CRUD example.",\n      generatedAt: Date.now(),\n    };\n  },\n});\n',
    "apps/web/convex/schema.ts":
      'import { defineSchema, defineTable } from "convex/server";\nimport { v } from "convex/values";\n\nexport default defineSchema({\n  todos: defineTable({\n    text: v.string(),\n    done: v.boolean(),\n    createdAt: v.number(),\n  }).index("by_created_at", ["createdAt"]),\n});\n',
    "apps/web/convex/todos.ts":
      'import { mutation, query } from "./_generated/server";\nimport { v } from "convex/values";\n\nexport const list = query({\n  args: {},\n  handler: async (ctx) => {\n    return await ctx.db\n      .query("todos")\n      .withIndex("by_created_at")\n      .order("desc")\n      .collect();\n  },\n});\n\nexport const create = mutation({\n  args: {\n    text: v.string(),\n  },\n  handler: async (ctx, args) => {\n    const trimmed = args.text.trim();\n    if (!trimmed) {\n      throw new Error("Todo text cannot be empty");\n    }\n\n    await ctx.db.insert("todos", {\n      text: trimmed,\n      done: false,\n      createdAt: Date.now(),\n    });\n  },\n});\n\nexport const toggle = mutation({\n  args: {\n    id: v.id("todos"),\n  },\n  handler: async (ctx, args) => {\n    const todo = await ctx.db.get(args.id);\n    if (!todo) {\n      throw new Error("Todo not found");\n    }\n\n    await ctx.db.patch(args.id, {\n      done: !todo.done,\n    });\n  },\n});\n',
    "apps/web/index.html":
      '<!doctype html>\n<html lang="en">\n  <head>\n    <meta charset="UTF-8" />\n    <link rel="icon" type="image/svg+xml" href="/favicon.svg" />\n    <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n    <title>Convex Cloudflare Pages Stack</title>\n  </head>\n  <body>\n    <div id="root"></div>\n    <script type="module" src="/src/main.tsx"></script>\n  </body>\n</html>\n',
    "apps/web/package.json":
      '{\n  "name": "web",\n  "version": "0.0.0",\n  "private": true,\n  "license": "UNLICENSED",\n  "type": "module",\n  "scripts": {\n    "dev": "npm-run-all --parallel dev:frontend dev:backend",\n    "dev:frontend": "vp dev",\n    "dev:backend": "convex dev",\n    "build": "vp build",\n    "format": "oxfmt",\n    "format:check": "oxfmt --check",\n    "preview": "vp preview",\n    "check": "pnpm run typecheck && pnpm run format:check",\n    "typecheck": "tsgo -b --pretty false",\n    "lint": "pnpm run check",\n    "test": "vp test run --passWithNoTests"\n  },\n  "dependencies": {\n    "@radix-ui/react-checkbox": "^1.3.3",\n    "@radix-ui/react-slot": "^1.2.3",\n    "class-variance-authority": "^0.7.1",\n    "clsx": "^2.1.1",\n    "convex": "1.34.1",\n    "lucide-react": "^0.525.0",\n    "npm-run-all": "^4.1.5",\n    "react": "^19.2.4",\n    "react-dom": "^19.2.4",\n    "tailwind-merge": "^3.5.0"\n  },\n  "devDependencies": {\n    "@tailwindcss/vite": "^4.2.2",\n    "@types/react": "^19.2.14",\n    "@types/react-dom": "^19.2.3",\n    "@typescript/native-preview": "7.0.0-dev.20260413.1",\n    "@vitejs/plugin-react": "^6.0.1",\n    "oxfmt": "0.44.0",\n    "tailwindcss": "^4.2.2",\n    "tailwindcss-animate": "^1.0.7",\n    "typescript": "5.9.2",\n    "vite": "^8.0.8",\n    "vite-plus": "0.1.16",\n    "vitest": "^4.1.4"\n  },\n  "engines": {\n    "node": ">=24.0.0"\n  },\n  "packageManager": "pnpm@9.15.0"\n}\n',
